    g_klej_s2: "Pomnóż powierzchnię przez zużycie z worka (typowo 4 kg/m² przy grzebieniu 6 mm, 5 kg/m² przy 10 mm) i podziel przez wagę worka.",
    g_klej_s3: "Policz osobno fugę — zależy od wymiaru płytki, jej grubości i szerokości spoiny — oraz same płytki z zapasem na docinki.",
    g_klej_tip: "Zużycie z worka dotyczy równego podłoża. Krzywa ściana wypija znacznie więcej kleju niż mówi etykieta; przy nierównościach ponad 5 mm najpierw wyrównaj podłoże, bo klej jest droższy od wylewki.",
    g_gladz_t: "Ile gładzi na ścianę",
    g_gladz_d: "Gładź liczy się w kilogramach na metr kwadratowy i milimetr warstwy. Dwie cienkie warstwy zamiast jednej grubej.",
    g_gladz_s1: "Policz pole ścian i sufitu i odejmij okna oraz drzwi. Powierzchnia to punkt wyjścia dla każdej warstwy.",
    g_gladz_s2: "Przyjmij zużycie z worka: gładź gipsowa około 1 kg/m² na milimetr warstwy, polimerowa około 1,2 kg/m². Pomnóż przez grubość warstwy.",
    g_gladz_s3: "Pomnóż przez liczbę warstw i podziel przez wagę worka. Zaokrąglij w górę — resztki worka nie kupisz.",
    g_gladz_tip: "Na surowym tynku pierwsza warstwa schodzi grubiej niż zakłada etykieta, bo wypełnia nierówności. Licz pierwszą warstwę jako 1,5 mm, a drugą jako 0,5 mm, i najpierw zagruntuj — bez gruntu gładź ciągnie wodę i pyli.",
    g_ocieplenie_t: "Ocieplenie domu styropianem",
    g_ocieplenie_d: "System ETICS to nie sam styropian: to jeszcze klej, kołki, siatka, warstwa zbrojąca i tynk. Każdy element liczy się z tej samej powierzchni.",
    g_ocieplenie_s1: "Policz pole elewacji: obwód budynku razy wysokość, minus okna i drzwi. Ościeża licz osobno, jeśli je ocieplasz.",
    g_ocieplenie_s2: "Dobierz grubość styropianu i policz paczki. Do tego kołki (typowo 6 sztuk na m², przy narożnikach i wyżej niż 8 m więcej) i klej — osobno do przyklejania, osobno do warstwy zbrojącej.",
    g_ocieplenie_s3: "Siatkę licz z zapasem około 10 % na zakłady, a tynk cienkowarstwowy z jego własnego zużycia na m².",
    g_ocieplenie_tip: "Liczba kołków to nie jedna wartość na cały dom. Strefa narożna wymaga ich gęściej niż środek ściany, a powyżej 8 m budynek wchodzi w wyższą strefę wiatrową. Sprawdź projekt albo wytyczne systemu, zanim zamówisz.",
    g_rozkroj_t: "Rozkrój płyty meblowej bez odpadu",
    g_rozkroj_d: "Ile płyt kupić na listę formatek i jak je poukładać, żeby odpad był jak najmniejszy. Rzaz piły też zabiera materiał.",
    g_rozkroj_s1: "Wypisz formatki: szerokość, długość i sztuki. Dodaj naddatek na okleinę, jeśli obrzeże ma być nakładane po docięciu.",
    g_rozkroj_s2: "Podaj format płyty i rzaz piły. Piła panelowa zabiera około 3–4 mm na każde cięcie; przy kilkudziesięciu cięciach to całe centymetry.",
    g_rozkroj_s3: "Sprawdź, czy formatki mogą być obracane. Płyta z usłojeniem albo wzorem nie może, i wtedy odpad rośnie — policz oba warianty i porównaj.",
    g_rozkroj_tip: "Wynik to plan cięcia, nie zamówienie. Zanim zamówisz, sprawdź, czy każda formatka mieści się na płycie w tę stronę, w którą zaplanował ją algorytm — przy usłojeniu obrót zmienia wygląd frontu, nawet gdy wymiar się zgadza.",

