    apppage_lead: "Ta sama matematyka co na stronie, w telefonie i bez zasięgu. Kalkulatory, katalog materiałów, pomieszczenia, projekty, wycena do PDF, przelicznik jednostek i mapa sklepów budowlanych.",
    apppage_meta: "LiczMat na Androida: darmowy kalkulator i optymalizator materiałów budowlanych. Katalog, pomieszczenia, projekty, wycena PDF i mapa sklepów. Liczy offline.",
