    g_malowanie_t: "How much paint for a room",
    g_malowanie_d: "Wall and ceiling area, openings deducted, converted into whole tins with an allowance for the second coat.",
    g_malowanie_s1: "Measure the room: length, width and height. Perimeter times height gives the wall area, length times width gives the ceiling.",
    g_malowanie_s2: "Deduct windows and doors. A typical window is about 1.5 m², a typical door about 1.8 m².",
    g_malowanie_s3: "Divide by the coverage printed on the tin and multiply by the number of coats. Round up to whole tins.",
    g_malowanie_tip: "The coverage on the label assumes a smooth, primed surface. Absorbent plaster drinks more paint, so allow extra or prime first.",

    g_plytki_t: "Tiles and adhesive for a bathroom",
    g_plytki_d: "Floor and walls in square metres, an allowance for cuts, adhesive and grout converted into bags.",
    g_plytki_s1: "Measure the floor and the walls separately. For walls take the perimeter times the tiled height, then deduct the door and window.",
    g_plytki_s2: "Add an allowance for cuts: 5–7% for a straight layout, 10–15% for large format or a diagonal layout.",
    g_plytki_s3: "Work out adhesive from the coverage for your trowel notch, and grout from the tile size and joint width.",
    g_plytki_tip: "Buy tiles from a single production batch. Batches differ in shade and calibration, and a month later that batch will be gone from the shop.",

    g_panele_t: "How many floor panels",
    g_panele_d: "Floor area, an allowance for cuts and a conversion into whole packs.",
    g_panele_s1: "Measure the floor: length times width. Measure alcoves and bays separately and add them.",
    g_panele_s2: "Add an allowance for cuts: 5% laying straight along the longer wall, 10% laying diagonally.",
    g_panele_s3: "Divide by the pack coverage printed on the packaging and round up to whole packs.",
    g_panele_tip: "Keep one full pack spare. A damaged board can only be swapped if you have exactly the same decor.",

    g_sciana_t: "Stud partition: profiles and boards",
    g_sciana_d: "How many CW and UW profiles, how many plasterboards and how much mineral wool for a wall of a given size.",
    g_sciana_s1: "Enter the wall width and height and the stud spacing — usually 60 cm, or 40 cm under a heavier finish.",
    g_sciana_s2: "CW studs come from the spacing; UW tracks are the floor and the ceiling, so twice the wall length.",
    g_sciana_s3: "Count boards for both faces of the wall with a 10% allowance for cuts. Wool is counted over the wall area.",
    g_sciana_tip: "Stagger the boards so the joints on one face do not line up with the joints on the other. The wall is stiffer and the seams crack less.",

    storespage_title: "Building stores near you",
    storespage_lead: "Find a DIY store, wholesaler or builders' yard by location or by name. The list of places comes from OpenStreetMap; the map and directions come from Google Maps.",
    storespage_meta: "Find a building store near you: DIY markets, wholesalers and builders' yards on a map, with directions to the one you pick.",

    note_coverage: "The coverage on the label (m²/l or m²/pack) assumes a smooth, primed surface. Absorbent plaster uses more. Only deduct openings if you are genuinely not painting them.",
    note_waste: "A 5–7% allowance is enough for a straight layout. Large format, diagonal or brick-bond layouts need 10–15%. Buy from a single batch.",
    note_wallpaper: "With a pattern repeat every strip is extended to a whole multiple of the repeat, so a roll yields fewer strips. A repeat of 0 means a paper with no pattern to match.",
    note_linear: "The saw kerf is subtracted at every cut after the first one in a bar, not at the first. First-fit decreasing gives a good, but not always optimal, cutting plan.",
    note_sheet: "Guillotine cutting: every cut runs right across the sheet, the way a panel saw works. Turn rotation off when the sheet has a grain or a directional pattern.",
    note_concrete: "The conversion assumes a 25 kg bag of dry mix yielding about 12.5 l of concrete. Check the yield on the bag — it differs between manufacturers.",
    note_mortar: "Adhesive usage depends on the trowel notch and how flat the substrate is. The figure here is the datasheet usage; on an uneven wall it can rise by half.",
    note_screed: "The conversion assumes a density of about 2.0 kg per litre of mortar. Anhydrite screeds and lightweight screeds have a different density — check the bag.",
    note_grout: "Grout usage rises with joint width and tile thickness, and falls with tile size. Large porcelain on a thin joint needs very little.",
    note_masonry: "Pieces per m² come from the block size including the joint. A 5% allowance covers cuts and breakages in transport.",
    note_insulation: "The number of anchors depends on building height and wind zone — 6 per m² is typical for the ground and first floor. Count mesh with a 10% overlap.",
    note_studwall: "60 cm spacing is standard under a 1.2 m board. Go down to 40 cm under a heavier finish or tiles. Boards are counted for both faces.",
    note_ceiling: "40 cm CD spacing and 90 cm hanger spacing is a typical ceiling under one board. Heavier loads need tighter spacing.",
    note_drylining: "The adhesive-dab method only works on a flat, sound substrate. Bigger deviations need a metal frame.",
    note_sheathing: "The result is a count of whole sheets with no cutting plan. If you need to know how to cut them, use the 2D sheet cutting calculator.",


