    g_plytki_d: "Boden und Wände in Quadratmetern, Verschnittzuschlag, Kleber und Fugenmasse in Säcken.",
    g_plytki_s1: "Rechne Boden und Wände getrennt. Für die Wände Umfang mal Fliesenhöhe, dann Tür und Fenster abziehen.",
    g_plytki_s2: "Rechne Verschnitt dazu: 5–7% bei geradem Verband, 10–15% bei Großformat oder diagonaler Verlegung.",
    g_plytki_s3: "Den Kleber aus dem Verbrauch für deine Zahnung rechnen, die Fugenmasse aus Fliesenmaß und Fugenbreite.",
    g_plytki_tip: "Kauf Fliesen aus einer Charge. Chargen unterscheiden sich in Farbton und Kaliber, und einen Monat später gibt es genau diese Charge nicht mehr.",

    g_panele_t: "Wie viele Bodenpaneele",
    g_panele_d: "Bodenfläche, Verschnittzuschlag und Umrechnung in ganze Pakete.",
    g_panele_s1: "Miss den Boden: Länge mal Breite. Nischen und Erker getrennt messen und dazurechnen.",
    g_panele_s2: "Rechne Verschnitt dazu: 5% bei gerader Verlegung entlang der längeren Wand, 10% bei diagonaler Verlegung.",
    g_panele_s3: "Teile durch die Paketfläche auf der Verpackung und runde auf ganze Pakete auf.",
    g_panele_tip: "Leg ein volles Paket zurück. Eine beschädigte Diele lässt sich nur tauschen, wenn du genau dasselbe Dekor hast.",

    g_sciana_t: "Ständerwand: Profile und Platten",
    g_sciana_d: "Wie viele CW- und UW-Profile, wie viele Gipskartonplatten und wie viel Mineralwolle für eine Wand der angegebenen Größe.",
    g_sciana_s1: "Gib Wandbreite und -höhe sowie den Ständerabstand ein — meist 60 cm, unter schwererer Beplankung 40 cm.",
    g_sciana_s2: "CW-Ständer ergeben sich aus dem Abstand; UW-Profile sind Boden und Decke, also die doppelte Wandlänge.",
    g_sciana_s3: "Platten für beide Wandseiten rechnen, mit 10% Verschnitt. Wolle über die Wandfläche rechnen.",
    g_sciana_tip: "Versetze die Platten, damit die Stöße auf einer Seite nicht auf denen der anderen liegen. Die Wand wird steifer und die Fugen reißen weniger.",

    storespage_title: "Baumärkte in deiner Nähe",
    storespage_lead: "Finde Baumarkt, Großhandel oder Baustofflager nach Standort oder Name. Die Liste kommt aus OpenStreetMap, Karte und Route von Google Maps.",
    storespage_meta: "Baumarkt in der Nähe finden: Baumärkte, Großhändler und Baustofflager auf der Karte, mit Route zum ausgewählten Standort.",

    note_coverage: "Die Ergiebigkeit auf dem Etikett (m²/l oder m²/Gebinde) gilt für glatten, grundierten Untergrund. Saugender Putz braucht mehr. Öffnungen nur abziehen, wenn du sie wirklich nicht streichst.",
    note_waste: "5–7% Zuschlag reichen bei geradem Verband. Großformat, Diagonal- oder Reihenverband brauchen 10–15%. Kauf aus einer Charge.",
    note_wallpaper: "Bei Rapport wird jede Bahn auf ein volles Vielfaches des Rapports verlängert, aus einer Rolle kommen also weniger Bahnen. Rapport 0 heißt Tapete ohne anzupassendes Muster.",
    note_linear: "Die Schnittfuge wird bei jedem Schnitt nach dem ersten in einer Stange abgezogen, nicht beim ersten. First-Fit-Decreasing liefert einen guten, aber nicht immer optimalen Zuschnitt.",
    note_sheet: "Guillotine-Zuschnitt: jeder Schnitt geht ganz durch die Platte, wie an der Formatkreissäge. Drehung ausschalten, wenn die Platte Maserung oder ein gerichtetes Dekor hat.",
    note_concrete: "Die Umrechnung geht von einem 25-kg-Sack Trockenmischung mit etwa 12,5 l Beton aus. Prüf die Ergiebigkeit auf dem Sack, sie ist herstellerabhängig.",
    note_mortar: "Der Kleberverbrauch hängt von der Zahnung und der Ebenheit des Untergrunds ab. Der Wert hier ist der Datenblattwert; auf einer schiefen Wand steigt er um die Hälfte.",
    note_screed: "Die Umrechnung geht von etwa 2,0 kg je Liter Mörtel aus. Anhydrit- und Leichtestriche haben eine andere Dichte — prüf den Sack.",
    note_grout: "Der Fugenverbrauch steigt mit Fugenbreite und Fliesendicke und sinkt mit dem Format. Großes Feinsteinzeug auf schmaler Fuge braucht sehr wenig.",
    note_masonry: "Die Stück je m² ergeben sich aus dem Steinmaß inklusive Fuge. 5% Zuschlag decken Verschnitt und Transportbruch.",
    note_insulation: "Die Dübelzahl hängt von Gebäudehöhe und Windzone ab — 6 je m² ist typisch für Erd- und erstes Obergeschoss. Gewebe mit 10% Überlappung rechnen.",
    note_studwall: "60 cm Abstand ist Standard unter einer 1,2-m-Platte. Unter schwererer Beplankung oder Fliesen auf 40 cm gehen. Platten für beide Seiten rechnen.",
    note_ceiling: "40 cm CD-Abstand und 90 cm Abhängerabstand sind typisch für eine einlagige Decke. Bei höherer Last müssen die Abstände enger werden.",
    note_drylining: "Die Ansetzbinder-Methode funktioniert nur auf ebenem, tragfähigem Untergrund. Größere Abweichungen brauchen eine Unterkonstruktion.",
    note_sheathing: "Das Ergebnis ist die Zahl ganzer Platten ohne Schnittplan. Wenn du wissen willst, wie du sie zuschneidest, nimm den 2D-Plattenzuschnitt.",


