    ck_p_currency: "Die Währung, in der du deine Preise rechnest. Unabhängig von der Sprache gewählt.",
    ck_p_theme: "Hell oder dunkel, wenn du es selbst gesetzt hast statt es dem System zu überlassen.",
    ck_p_signed_in: "Die Kontostufe (LiczMat oder LiczMat Pro), bei der Anmeldung gemerkt. Die Rechner laden kein Firebase, brauchen das aber, um zu entscheiden, ob sie ein Konto vorschlagen, und um den Kopf der Seite zu markieren, wenn jemand angemeldet ist. Sie enthält keine E-Mail-Adresse und nichts anderes über dich und schaltet nichts frei.",
