    /* Guides added 2026-08-08: adhesive, skim coat, ETICS, board cutting. */
    g_klej_t: "Wie viel Fliesenkleber",
    g_klej_d: "Der Kleberverbrauch folgt der Zahnung, und die Zahnung dem Fliesenformat. Dazu die Fugenmasse und die Fliesen selbst mit Verschnitt.",
    g_klej_s1: "Zahnung nach Format wählen: 6 mm für kleine Wandfliesen, 8–10 mm für Feinsteinzeug 60×60, 12 mm und Buttering-Floating für Großformate.",
    g_klej_s2: "Die Fläche mit dem Verbrauch vom Sack multiplizieren (typisch 4 kg/m² bei 6-mm-Zahnung, 5 kg/m² bei 10 mm) und durch das Sackgewicht teilen.",
    g_klej_s3: "Die Fugenmasse getrennt rechnen — sie folgt Fliesenmaß, Dicke und Fugenbreite — und die Fliesen selbst mit Verschnittzuschlag.",
    g_klej_tip: "Der Verbrauch auf dem Sack gilt für einen ebenen Untergrund. Eine krumme Wand schluckt weit mehr Kleber als das Etikett sagt; ab etwa 5 mm Unebenheit zuerst den Untergrund ausgleichen, denn Kleber ist teurer als Ausgleichsmasse.",
    g_gladz_t: "Wie viel Spachtelmasse für eine Wand",
    g_gladz_d: "Spachtelmasse rechnet man in Kilogramm je Quadratmeter und Millimeter Schicht. Zwei dünne Lagen statt einer dicken.",
    g_gladz_s1: "Wand- und Deckenfläche ausrechnen, Fenster und Türen abziehen. Diese Fläche ist der Ausgangspunkt jeder Schicht.",
    g_gladz_s2: "Verbrauch vom Sack nehmen: Gipsspachtel etwa 1 kg/m² je Millimeter, Polymerspachtel etwa 1,2 kg/m². Mit der Schichtdicke multiplizieren.",
    g_gladz_s3: "Mit der Zahl der Schichten multiplizieren und durch das Sackgewicht teilen. Aufrunden — einen halben Sack gibt es nicht.",
    g_gladz_tip: "Auf rohem Putz geht die erste Schicht dicker auf als das Etikett annimmt, weil sie Unebenheiten füllt. Rechne die erste Lage mit 1,5 mm und die zweite mit 0,5 mm, und grundiere vorher — ohne Grundierung zieht die Spachtelmasse Wasser und kreidet.",
    g_ocieplenie_t: "Haus mit EPS dämmen",
    g_ocieplenie_d: "Ein WDVS ist nicht nur der Styropor: dazu kommen Kleber, Dübel, Gewebe, Armierungsschicht und Putz. Alles davon rechnet sich aus derselben Fläche.",
    g_ocieplenie_s1: "Fassadenfläche ausrechnen: Gebäudeumfang mal Höhe, minus Fenster und Türen. Laibungen getrennt rechnen, wenn sie gedämmt werden.",
    g_ocieplenie_s2: "Dämmstärke wählen und die Pakete zählen. Dazu die Dübel (typisch 6 je m², an Ecken und über 8 m mehr) und den Kleber — einmal zum Ankleben, einmal für die Armierungsschicht.",
    g_ocieplenie_s3: "Beim Gewebe rund 10 % für Überlappungen zugeben, den Dünnschichtputz aus seinem eigenen Verbrauch je m² rechnen.",
    g_ocieplenie_tip: "Die Dübelzahl ist keine einzelne Zahl fürs ganze Haus. Die Eckzone braucht sie dichter als die Wandmitte, und über 8 m rutscht das Gebäude in eine höhere Windzone. Vor der Bestellung Planung oder Systemvorgabe prüfen.",
    g_rozkroj_t: "Möbelplatte mit wenig Verschnitt zuschneiden",
    g_rozkroj_d: "Wie viele Platten eine Teileliste braucht und wie man sie anordnet, damit der Verschnitt klein bleibt. Die Schnittfuge frisst ebenfalls Material.",
    g_rozkroj_s1: "Teile auflisten: Breite, Länge und Stückzahl. Zugabe für die Kante einplanen, wenn die Umleimer nach dem Zuschnitt kommen.",
    g_rozkroj_s2: "Plattenformat und Schnittfuge angeben. Eine Plattensäge nimmt je Schnitt etwa 3–4 mm; über ein paar Dutzend Schnitte sind das ganze Zentimeter.",
    g_rozkroj_s3: "Festlegen, ob Teile gedreht werden dürfen. Eine Platte mit Maserung oder Dekor darf das nicht, und der Verschnitt steigt — beide Varianten rechnen und vergleichen.",
    g_rozkroj_tip: "Das Ergebnis ist ein Schnittplan, keine Bestellung. Vor der Bestellung prüfen, ob jedes Teil so liegt, wie der Algorithmus es gedreht hat — bei Maserung ändert eine Drehung das Aussehen der Front, auch wenn das Maß stimmt.",

