    /* Guides added 2026-08-08: adhesive, skim coat, ETICS, board cutting. */
    g_klej_t: "Скільки клею для плитки",
    g_klej_d: "Витрата клею залежить від гребінки, а гребінка — від формату плитки. До цього затирка і сама плитка із запасом на підрізку.",
    g_klej_s1: "Вибери гребінку під формат: 6 мм для дрібної настінної, 8–10 мм для керамограніту 60×60, 12 мм і комбінований метод для великого формату.",
    g_klej_s2: "Помнож площу на витрату з мішка (типово 4 кг/м² при гребінці 6 мм, 5 кг/м² при 10 мм) і поділи на вагу мішка.",
    g_klej_s3: "Затирку рахуй окремо — вона залежить від розміру плитки, її товщини й ширини шва — і саму плитку із запасом на підрізку.",
    g_klej_tip: "Витрата на мішку стосується рівної основи. Крива стіна вип’є значно більше клею, ніж каже етикетка; за нерівності понад приблизно 5 мм спочатку вирівняй основу, бо клей дорожчий за самовирівнювальну суміш.",
    g_gladz_t: "Скільки шпаклівки на стіну",
    g_gladz_d: "Шпаклівка рахується в кілограмах на квадратний метр і міліметр шару. Два тонкі шари замість одного товстого.",
    g_gladz_s1: "Порахуй площу стін і стелі та відніми вікна й двері. Ця площа — відправна точка для кожного шару.",
    g_gladz_s2: "Візьми витрату з мішка: гіпсова шпаклівка близько 1 кг/м² на міліметр, полімерна близько 1,2 кг/м². Помнож на товщину шару.",
    g_gladz_s3: "Помнож на кількість шарів і поділи на вагу мішка. Округли вгору — пів мішка не купиш.",
    g_gladz_tip: "На сирій штукатурці перший шар лягає товщіше, ніж припускає етикетка, бо заповнює нерівності. Рахуй перший шар як 1,5 мм, а другий як 0,5 мм, і спершу ґрунтуй — без ґрунтовки шпаклівка тягне воду й пилить.",
    g_ocieplenie_t: "Утеплення будинку пінопластом",
    g_ocieplenie_d: "Система ETICS — це не лише пінопласт: ще клей, дюбелі, сітка, армувальний шар і штукатурка. Усе рахується з тієї самої площі.",
    g_ocieplenie_s1: "Порахуй площу фасаду: периметр будинку на висоту, мінус вікна й двері. Укоси рахуй окремо, якщо їх утеплюєш.",
    g_ocieplenie_s2: "Вибери товщину пінопласту й порахуй пачки. До цього дюбелі (типово 6 на м², у кутах і вище 8 м більше) і клей — окремо на приклеювання, окремо на армувальний шар.",
    g_ocieplenie_s3: "На сітку додай близько 10 % на нахлести, а тонкошарову штукатурку рахуй з її власної витрати на м².",
    g_ocieplenie_tip: "Кількість дюбелів — не одне число на весь будинок. Кутова зона потребує їх густіше, ніж середина стіни, а вище 8 м будівля переходить у вищу вітрову зону. Перевір проєкт або вказівки системи, перш ніж замовляти.",
    g_rozkroj_t: "Розкрій меблевої плити без відходів",
    g_rozkroj_d: "Скільки плит купити на список деталей і як їх розкласти, щоб відходів було якнайменше. Пропил пилки теж з’їдає матеріал.",
    g_rozkroj_s1: "Випиши деталі: ширина, довжина й кількість. Додай припуск на кромку, якщо її клеять після розкрою.",
    g_rozkroj_s2: "Вкажи формат плити і пропил. Форматний верстат бере близько 3–4 мм на кожен різ; на кількох десятках різів це цілі сантиметри.",
    g_rozkroj_s3: "Виріши, чи можна повертати деталі. Плита з текстурою або малюнком — ні, і відходи зростають; порахуй обидва варіанти й порівняй.",
    g_rozkroj_tip: "Результат — це план розкрою, а не замовлення. Перед замовленням перевір, чи кожна деталь лежить так, як її повернув алгоритм: при текстурі поворот змінює вигляд фасаду, навіть коли розмір збігається.",

