    ck_p_signed_in: "Úroveň účtu (LiczMat nebo LiczMat Pro) zapamatovaná při přihlášení. Kalkulačky nenačítají Firebase a potřebují to, aby věděly, zda nabízet účet, a aby v hlavičce označily, že je někdo přihlášen. Neobsahuje e-mail ani žádné jiné údaje o tobě a nic neodemyká.",
