    storespage_title: "Stavebniny vo tvojom okolí",
    storespage_lead: "Nájdi hobbymarket, veľkoobchod alebo stavebniny podľa polohy alebo názvu. Zoznam miest berieme z OpenStreetMap, mapu a navigáciu zabezpečuje Google Maps.",
