    note_sheet: "Gilotínový rez: každý rez ide cez celú dosku, ako na formátovacej píle. Otáčanie vypni, keď má doska kresbu alebo smerový dekor.",
    note_concrete: "Prepočet predpokladá vrece 25 kg suchej zmesi, ktoré dá asi 12,5 l betónu. Skontroluj výdatnosť na vreci, líši sa podľa výrobcu.",
    note_mortar: "Spotreba lepidla závisí od zuba hladidla a rovinnosti podkladu. Uvedená hodnota je z technického listu; na krivej stene môže vzrásť o polovicu.",
    note_screed: "Prepočet predpokladá hustotu asi 2,0 kg na liter malty. Anhydritové a ľahčené potery majú inú hustotu — skontroluj vrece.",
    note_grout: "Spotreba škárovacej hmoty rastie so šírkou škáry a hrúbkou dlaždice a klesá s formátom. Pri veľkej dlažbe na úzkej škáre vyjde veľmi málo.",
