    guide_calcs_back: "Návody s touto kalkulačkou",
    g_klej_t: "Koľko lepidla na obklady",
    g_klej_d: "Spotreba lepidla sa riadi hrebeňom a hrebeň formátom obkladu. K tomu škárovacia hmota a samotné obklady s prierezom.",
    g_klej_s1: "Vyber hrebeň podľa formátu: 6 mm na malé obklady, 8–10 mm na dlažbu 60×60, 12 mm a kombinovaná metóda na veľký formát.",
    g_klej_s2: "Vynásob plochu spotrebou z vreca (typicky 4 kg/m² pri hrebeni 6 mm, 5 kg/m² pri 10 mm) a vydeľ hmotnosťou vreca.",
    g_klej_s3: "Škárovaciu hmotu počítaj zvlášť — riadi sa rozmerom obkladu, jeho hrúbkou a šírkou škáry — a obklady s prierezom.",
    g_klej_tip: "Spotreba na vreci platí pre rovný podklad. Krivá stena vypije podstatne viac lepidla, než hovorí etiketa; nad zhruba 5 mm nerovnosti najprv vyrovnaj podklad, lebo lepidlo je drahšie než stierka.",
    g_gladz_t: "Koľko štuku na stenu",
    g_gladz_d: "Štuk sa počíta v kilogramoch na meter štvorcový a milimeter vrstvy. Dve tenké vrstvy namiesto jednej hrubej.",
    g_gladz_s1: "Spočítaj plochu stien a stropu a odčítaj okná a dvere. Táto plocha je základ pre každú vrstvu.",
    g_gladz_s2: "Vezmi spotrebu z vreca: sadrový štuk asi 1 kg/m² na milimeter, polymérový asi 1,2 kg/m². Vynásob hrúbkou vrstvy.",
    g_gladz_s3: "Vynásob počtom vrstiev a vydeľ hmotnosťou vreca. Zaokrúhli nahor — pol vreca nekúpiš.",
    g_gladz_tip: "Na surovej omietke ide prvá vrstva hrubšie, než etiketa predpokladá, lebo vypĺňa nerovnosti. Počítaj prvú vrstvu ako 1,5 mm a druhú ako 0,5 mm a najprv penetruj — bez penetrácie štuk ťahá vodu a práši.",
    g_ocieplenie_t: "Zateplenie domu polystyrénom",
    g_ocieplenie_d: "ETICS nie je len polystyrén: patrí k nemu lepidlo, hmoždinky, sieťka, výstužná vrstva a omietka. Všetko sa počíta z rovnakej plochy.",
    g_ocieplenie_s1: "Spočítaj plochu fasády: obvod budovy krát výška, mínus okná a dvere. Ostenie počítaj zvlášť, ak ho zatepľuješ.",
    g_ocieplenie_s2: "Vyber hrúbku polystyrénu a spočítaj balíky. K tomu hmoždinky (typicky 6 na m², v rohoch a nad 8 m viac) a lepidlo — zvlášť na lepenie, zvlášť na výstužnú vrstvu.",
    g_ocieplenie_s3: "Pri sieťke pridaj asi 10 % na presahy a tenkovrstvovú omietku počítaj z jej vlastnej spotreby na m².",
    g_ocieplenie_tip: "Počet hmoždiniek nie je jedno číslo pre celý dom. Rohová zóna ich potrebuje hustejšie než stred steny a nad 8 m sa budova posúva do vyššej veternej oblasti. Pred objednaním skontroluj projekt alebo pokyny systému.",
    g_rozkroj_t: "Rez nábytkovej dosky s malým prierezom",
    g_rozkroj_d: "Koľko dosiek kúpiť na zoznam dielcov a ako ich rozložiť, aby bol odpad čo najmenší. Prierez píly tiež uberá materiál.",
    g_rozkroj_s1: "Vypíš dielce: šírka, dĺžka a kusy. Pridaj nadmieru na hranu, ak sa olepuje až po reze.",
    g_rozkroj_s2: "Zadaj formát dosky a prierez píly. Formátovacia píla uberie asi 3–4 mm na každý rez; pri pár desiatkach rezov sú to celé centimetre.",
    g_rozkroj_s3: "Rozhodni, či sa dielce smú otáčať. Doska s kresbou alebo dekorom nesmie a odpad rastie — spočítaj obe varianty a porovnaj.",
    g_rozkroj_tip: "Výsledok je plán rezu, nie objednávka. Pred objednaním skontroluj, či každý dielec leží tak, ako ho algoritmus otočil — pri kresbe otočenie mení vzhľad čela, aj keď rozmer sedí.",
