    /* Session 29 — /liczmat-pro/, the public page for LiczMat Pro. */
    propage_meta: "LiczMat Pro: klienti, zákazky, cenové ponuky, termíny a história práce vedľa kalkulačiek. Čo predplatné Pro obsahuje, koľko stojí a čo v ňom nie je.",
