    /* Session 29 — /liczmat-pro/, the public page for LiczMat Pro. */
    propage_meta: "LiczMat Pro: clienți, comenzi, oferte, termene și istoricul lucrării lângă calculatoare. Ce cuprinde abonamentul Pro, cât costă și ce nu are.",
    propage_h_mods: "Ce cuprinde LiczMat Pro",
    propage_mods_d: "Cinci module. Stau lângă ce calculezi deja — nu înlocuiesc calculatoarele, ci adaugă conducerea lucrării.",
    propage_h_free: "Ce ai fără Pro",
    propage_free_d: "Pentru asta nu plătești. Calculul merge fără cont și așa rămâne.",
    propage_free_1: "Toate calculatoarele cu rezultatul complet și catalogul de materiale.",
    propage_free_2: "Proiecte, încăperi și calcule salvate — în acest browser, fără înregistrare.",
    propage_free_3: "Liste de materiale și costurile proiectului. Un cont gratuit adaugă sincronizarea cu telefonul și devizul de trimis prin link.",
    propage_h_not: "Ce nu face LiczMat Pro",
    propage_not_1: "Nu este ERP și nu este program de contabilitate: fără facturi, taxe, stoc sau salarii.",
    propage_not_2: "O ofertă înseamnă material, manoperă, costuri suplimentare, adaos și total. Fără reduceri, numere și date de emitere.",
