    g_plytki_s2: "Dodaj rezervu za rezanje: 5–7% kod ravnog slaganja, 10–15% kod velikog formata ili dijagonale.",
    g_plytki_s3: "Ljepilo računaj iz potrošnje za odabranu nazubljenu gletericu, fugir masu iz dimenzije pločice i širine fuge.",
    g_plytki_tip: "Kupuj pločice iz jedne proizvodne serije. Serije se razlikuju u nijansi i kalibru, a za mjesec dana te serije više neće biti u trgovini.",
    g_panele_t: "Koliko panela za pod",
    g_panele_d: "Površina poda, rezerva za rezanje i preračun u cijela pakiranja.",
    g_panele_s1: "Izmjeri pod: duljina puta širina. Niše i erkere izmjeri odvojeno i dodaj.",
    g_panele_s2: "Dodaj rezervu za rezanje: 5% kod ravnog polaganja uz dulji zid, 10% kod dijagonalnog polaganja.",
    g_panele_s3: "Podijeli s površinom pakiranja s ambalaže i zaokruži naviše na cijela pakiranja.",
    g_panele_tip: "Ostavi jedno cijelo pakiranje u rezervi. Oštećenu dasku zamijeniš samo ako imaš točno isti dekor.",
    g_sciana_t: "GK pregrada: profili i ploče",
    g_sciana_d: "Koliko CW i UW profila, koliko gips-kartonskih ploča i koliko vune za pregradu zadanih dimenzija.",
    g_sciana_s1: "Unesi širinu i visinu pregrade i razmak profila — najčešće 60 cm, pod težom oblogom 40 cm.",
    g_sciana_s2: "CW profili proizlaze iz razmaka, UW profili su pod i strop, dakle dvostruka duljina zida.",
    g_sciana_s3: "Ploče računaj za obje strane pregrade, s rezervom 10% za rezanje. Vunu računaj na površinu zida.",
    g_sciana_tip: "Ploče postavljaj s pomakom da spojevi na jednoj strani ne padnu na isto mjesto kao na drugoj. Zid je krući, a fuge manje pucaju.",
    storespage_title: "Građevinske trgovine u blizini",
    storespage_lead: "Nađi građevinski market, veletrgovinu ili skladište po lokaciji ili nazivu. Popis mjesta dolazi iz OpenStreetMapa, kartu i navigaciju daje Google Maps.",
    storespage_meta: "Nađi građevinsku trgovinu u blizini: marketi, veletrgovine i skladišta na karti, s rutom do odabranog mjesta.",
    note_coverage: "Izdašnost s etikete (m²/l ili m²/pakiranje) vrijedi za glatku, impregniranu podlogu. Upojna žbuka troši više. Otvore odbijaj samo ako ih doista ne bojaš.",
    note_waste: "Rezerva 5–7% dovoljna je kod ravnog slaganja. Veliki format, dijagonala ili slaganje u cigli traže 10–15%. Kupuj iz jedne serije.",
    note_wallpaper: "Kod tapete s raportom svaka traka produljuje se na cijeli višekratnik raporta, pa iz role izlazi manje traka. Raport 0 znači tapetu bez uzorka za spajanje.",
    note_linear: "Rez pile odbija se kod svakog sljedećeg reza u šipki, ne kod prvog. Algoritam first-fit decreasing daje dobar, ali ne uvijek optimalan raspored.",
    note_sheet: "Giljotinsko rezanje: svaki rez ide kroz cijelu ploču, kao na formatnoj pili. Isključi rotaciju kad ploča ima teksturu ili usmjeren uzorak.",
    note_concrete: "Preračun pretpostavlja vreću od 25 kg suhe mješavine koja daje oko 12,5 l betona. Provjeri izdašnost na vreći, razlikuje se među proizvođačima.",
    note_mortar: "Potrošnja ljepila ovisi o zubu gleterice i ravnosti podloge. Navedena vrijednost je iz tehničkog lista; na krivom zidu može narasti za polovicu.",
    note_screed: "Preračun pretpostavlja gustoću oko 2,0 kg po litri morta. Anhidritni i laki estrisi imaju drugu gustoću — provjeri vreću.",
    note_grout: "Potrošnja fugir mase raste sa širinom fuge i debljinom pločice, a pada s formatom. Kod velikog gresa na uskoj fugi ispada vrlo malo.",
    note_masonry: "Broj komada po m² proizlazi iz dimenzije bloka zajedno s fugom. Rezerva od 5% pokriva rezanje i lomove u transportu.",
    note_insulation: "Broj tipli ovisi o visini zgrade i vjetrovnoj zoni — 6 kom/m² tipično je za prizemlje i prvi kat. Mrežicu računaj s preklopom 10%.",
    note_studwall: "Razmak 60 cm standard je pod ploču od 1,2 m. Pod težu oblogu ili pločice spusti na 40 cm. Ploče računaj za obje strane.",
    note_ceiling: "Razmak nosivih CD 40 cm i vješalica 90 cm tipičan je strop pod jednu ploču. Kod većeg opterećenja razmake treba zgusnuti.",
    note_drylining: "Metoda na ljepilo u točkama radi samo na ravnoj, nosivoj podlozi. Veća odstupanja traže potkonstrukciju.",
    note_sheathing: "Rezultat je broj cijelih ploča bez plana rezanja. Ako želiš znati kako ih izrezati, upotrijebi kalkulator rezanja ploča 2D.",
