    ck_p_signed_in: "Nivo naloga (LiczMat ili LiczMat Pro) zapamćen pri prijavi. Kalkulatori ne učitavaju Firebase, a ovo im treba da znaju da li da ponude nalog i da u zaglavlju označe da je neko prijavljen. Ne sadrži adresu e-pošte ni bilo koje druge podatke o tebi i ništa ne otključava.",
