    g_klej_s1: "Выбери гребёнку под формат: 6 мм для мелкой настенной, 8–10 мм для керамогранита 60×60, 12 мм и комбинированный метод для крупного формата.",
    g_klej_s2: "Умножь площадь на расход с мешка (типично 4 кг/м² при гребёнке 6 мм, 5 кг/м² при 10 мм) и раздели на вес мешка.",
    g_klej_s3: "Затирку считай отдельно — она зависит от размера плитки, её толщины и ширины шва — и саму плитку с запасом на подрезку.",
    g_klej_tip: "Расход на мешке относится к ровному основанию. Кривая стена выпьет заметно больше клея, чем говорит этикетка; при неровности больше примерно 5 мм сначала выровняй основание, потому что клей дороже самовыравнивающейся смеси.",
    g_gladz_t: "Сколько шпаклёвки на стену",
    g_gladz_d: "Шпаклёвка считается в килограммах на квадратный метр и миллиметр слоя. Два тонких слоя вместо одного толстого.",
    g_gladz_s1: "Посчитай площадь стен и потолка и вычти окна и двери. Эта площадь — отправная точка для каждого слоя.",
    g_gladz_s2: "Возьми расход с мешка: гипсовая шпаклёвка около 1 кг/м² на миллиметр, полимерная около 1,2 кг/м². Умножь на толщину слоя.",
    g_gladz_s3: "Умножь на число слоёв и раздели на вес мешка. Округли вверх — полмешка не купишь.",
    g_gladz_tip: "На сырой штукатурке первый слой ложится толще, чем предполагает этикетка, потому что заполняет неровности. Считай первый слой как 1,5 мм, а второй как 0,5 мм, и сначала грунтуй — без грунтовки шпаклёвка тянет воду и пылит.",
    g_ocieplenie_t: "Утепление дома пенопластом",
    g_ocieplenie_d: "Система ETICS — это не только пенопласт: ещё клей, дюбели, сетка, армирующий слой и штукатурка. Всё считается с той же площади.",
    g_ocieplenie_s1: "Посчитай площадь фасада: периметр дома на высоту, минус окна и двери. Откосы считай отдельно, если их утепляешь.",
    g_ocieplenie_s2: "Выбери толщину пенопласта и посчитай пачки. Плюс дюбели (типично 6 на м², в углах и выше 8 м больше) и клей — отдельно на приклеивание, отдельно на армирующий слой.",
    g_ocieplenie_s3: "На сетку добавь около 10 % на нахлёсты, а тонкослойную штукатурку считай из её собственного расхода на м².",
    g_ocieplenie_tip: "Количество дюбелей — не одно число на весь дом. Угловая зона требует их гуще, чем середина стены, а выше 8 м здание переходит в более высокую ветровую зону. Проверь проект или указания системы, прежде чем заказывать.",
    g_rozkroj_t: "Раскрой мебельной плиты без отходов",
    g_rozkroj_d: "Сколько плит купить на список деталей и как их разложить, чтобы отходов было как можно меньше. Пропил пилы тоже съедает материал.",
    g_rozkroj_s1: "Выпиши детали: ширина, длина и количество. Добавь припуск на кромку, если её клеят после раскроя.",
    g_rozkroj_s2: "Укажи формат плиты и пропил. Форматный станок берёт около 3–4 мм на каждый рез; на нескольких десятках резов это целые сантиметры.",
    g_rozkroj_s3: "Реши, можно ли поворачивать детали. Плита с текстурой или рисунком — нельзя, и отходы растут; посчитай оба варианта и сравни.",
    g_rozkroj_tip: "Результат — это план раскроя, а не заказ. Перед заказом проверь, лежит ли каждая деталь так, как её повернул алгоритм: при текстуре поворот меняет вид фасада, даже когда размер совпадает.",
    nav_app_page: "Приложение",
    apppage_title: "LiczMat для Android",
    apppage_lead: "Та же математика, что на сайте, в телефоне и без связи. Калькуляторы, каталог материалов, помещения, проекты, смета в PDF, конвертер единиц и карта строительных магазинов.",
    apppage_meta: "LiczMat для Android: бесплатный калькулятор и оптимизатор строительных материалов. Каталог материалов, помещения, проекты, смета в PDF и карта магазинов.",
