    /* Session 29 — /liczmat-pro/, the public page for LiczMat Pro. */
    propage_meta: "LiczMat Pro: клиенты, заказы, предложения, сроки и история работы рядом с калькуляторами. Что входит в план Pro, сколько он стоит и чего в нём нет.",
    propage_h_mods: "Что входит в LiczMat Pro",
    propage_mods_d: "Пять модулей. Они стоят рядом с тем, что ты уже считаешь — не заменяют калькуляторы, а добавляют к ним ведение работы.",
    propage_h_free: "Что есть без Pro",
    propage_free_d: "За это ты не платишь. Считать можно без аккаунта, и так останется.",
    propage_free_1: "Все калькуляторы с полным результатом и каталог материалов.",
    propage_free_2: "Проекты, помещения и сохранённые расчёты — в этом браузере, без регистрации.",
    propage_free_3: "Списки материалов и расходы проекта. Бесплатный аккаунт добавляет синхронизацию с телефоном и смету, которой можно поделиться ссылкой.",
    propage_h_not: "Чего LiczMat Pro не делает",
    propage_not_1: "Это не ERP и не бухгалтерия: без счетов-фактур, налогов, склада и кадров.",
    propage_not_2: "Предложение — это материал, работа, дополнительные расходы, наценка и сумма. Без скидок, номеров и дат выставления.",
    propage_not_3: "Сроки показывают дедлайны заказов. Это не второй Google Календарь, и уведомлений он не шлёт.",
    propage_h_pay: "Сколько стоит",
    propage_h_how: "Как включить Pro",
    propage_how_1: "Создай бесплатный аккаунт LiczMat — план держится аккаунта, а не браузера.",
    propage_how_2: "Оформи подписку на странице своего аккаунта. Это единственное место, где LiczMat берёт деньги; оплату обрабатывает Stripe.",
    propage_how_3: "Пять модулей Pro откроются сами, на том же аккаунте.",
    propage_local: "Данные Pro — клиенты, заказы и предложения — остаются в памяти этого браузера. В приложении для Android их нет: синхронизация охватывает проекты, помещения, расчёты и списки материалов.",
    clipage_title: "Клиенты",
    clipage_lead: "Список клиентов LiczMat Pro: контактные данные, заметки и проекты, которые ты для них считаешь.",
